create or replace function public.dating_redeem_verified_capture(p_user uuid,p_capture text) returns timestamptz language plpgsql security definer set search_path='' as $$ declare v_exp timestamptz; begin if coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb->>'role' is distinct from 'service_role' and current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then raise exception 'Forbidden'; end if; perform 1 from public.dating_members where user_id=p_user for update; if not found then raise exception 'Profile missing'; end if; select greatest(now(),coalesce(paid_until,now()))+interval '30 days' into v_exp from public.dating_members where user_id=p_user; insert into private.dating_payment_redemptions(capture_id,user_id,amount_cents,currency,expires_at) values(p_capture,p_user,499,'CAD',v_exp); update public.dating_members set paid_until=v_exp where user_id=p_user; return v_exp; end $$;
revoke all on function public.dating_redeem_verified_capture(uuid,text) from public,anon,authenticated;
grant execute on function public.dating_redeem_verified_capture(uuid,text) to service_role;
